	private static final class ManyRangeFamily implements AdjacencySourceFamily {

		private final ManyRangeScanner[] scanners;
		private final DelayOrder delayOrder;
		private final AtomicInteger concurrent = new AtomicInteger();
		private final AtomicInteger maximumConcurrent = new AtomicInteger();
		private final ConcurrentLinkedQueue<Long> completionOrder = new ConcurrentLinkedQueue<>();

		private ManyRangeFamily(int scannerCount) {
			this(scannerCount, DelayOrder.OVERLAP);
		}

		private ManyRangeFamily(int scannerCount, DelayOrder delayOrder) {
			this.delayOrder = delayOrder;
			scanners = new ManyRangeScanner[scannerCount];
			for (int i = 0; i < scanners.length; i++) {
				scanners[i] = new ManyRangeScanner(this);
			}
		}

		@Override
		public AdjacencySourceScanner primary() {
			return scanners[0];
		}

		@Override
		public AdjacencySourceScanner scanner(int plane) {
			return scanners[plane];
		}

		public int workerScannerCount() {
			return scanners.length;
		}

		public AdjacencySourceScanner workerScanner(int worker) {
			return scanners[worker];
		}

		public boolean isPlaneActive(int plane) {
			return true;
		}

		@Override
		public int activeStreamCount() {
			return 4;
		}

		@Override
		public long snapshotRevision() {
			return 7;
		}

		@Override
		public void cancel() {
		}

		@Override
		public void close() {
		}

		private void enter(LmdbAdjacencyCoverage coverage) {
			int active = concurrent.incrementAndGet();
			maximumConcurrent.accumulateAndGet(active, Math::max);
			try {
				long delayMillis = switch (delayOrder) {
				case OVERLAP -> 75;
				case ASCENDING -> selectedOrdinal(coverage) * 8L;
				case DESCENDING -> (ManyRangeScanner.PREDICATE_COUNT - 1L - selectedOrdinal(coverage)) * 8L;
				case NONE -> 0;
				};
				if (delayMillis > 0) {
					Thread.sleep(delayMillis);
				}
			} catch (InterruptedException e) {
				concurrent.decrementAndGet();
				Thread.currentThread().interrupt();
				throw new AssertionError("interrupted while observing predicate-range overlap", e);
			}
		}

		private void exit(int plane, LmdbAdjacencyCoverage coverage) {
			if (coverage.selectedPredicateCount() > 0) {
				completionOrder.add((long) plane << 32 | selectedOrdinal(coverage));
			}
			concurrent.decrementAndGet();
		}

		private static int selectedOrdinal(LmdbAdjacencyCoverage coverage) {
			if (coverage.selectedPredicateCount() == 0) {
				return 0;
			}
			long predicate = coverage.selectedPredicateAt(0);
			for (int ordinal = 0; ordinal < ManyRangeScanner.PREDICATE_COUNT; ordinal++) {
				if (predicate == ManyRangeScanner.predicate(ordinal)) {
					return ordinal;
				}
			}
			throw new AssertionError("unexpected selected predicate " + predicate);
		}

		private int maximumConcurrent() {
			return maximumConcurrent.get();
		}
	}

	private static final class ManyRangeScanner implements AdjacencySourceScanner {

		private static final int PREDICATE_COUNT = 8;

		private final ManyRangeFamily family;

		private ManyRangeScanner(ManyRangeFamily family) {
			this.family = family;
		}

		@Override
		public void scanPredicates(PredicateConsumer consumer) {
			for (int i = 0; i < PREDICATE_COUNT; i++) {
				consumer.predicate(predicate(i));
			}
		}

		@Override
		public void scanContexts(ContextConsumer consumer) {
		}

		@Override
		public void scanOutgoing(boolean explicit, GroupConsumer consumer) {
			scan(true, explicit, LmdbAdjacencyCoverage.full(), consumer);
		}

		@Override
		public void scanOutgoing(boolean explicit, LmdbAdjacencyCoverage coverage, GroupConsumer consumer) {
			scan(true, explicit, coverage, consumer);
		}

		@Override
		public void scanIncoming(boolean explicit, GroupConsumer consumer) {
			scan(false, explicit, LmdbAdjacencyCoverage.full(), consumer);
		}

		@Override
		public void scanIncoming(boolean explicit, LmdbAdjacencyCoverage coverage, GroupConsumer consumer) {
			scan(false, explicit, coverage, consumer);
		}

		public boolean supportsPredicatePartitionedScan(boolean outgoing) {
			return true;
		}

		private void scan(boolean outgoing, boolean explicit, LmdbAdjacencyCoverage coverage,
				GroupConsumer consumer) {
			family.enter(coverage);
			int plane = outgoing
					? explicit ? LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT
							: LmdbAdjacencyPlane.PLANE_OUTGOING_INFERRED
					: explicit ? LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT
							: LmdbAdjacencyPlane.PLANE_INCOMING_INFERRED;
			try {
				for (int i = 0; i < PREDICATE_COUNT; i++) {
					long predicate = predicate(i);
					if (coverage.covers(predicate)) {
						consumer.begin(ValueIds.createId(ValueIds.T_URI, 100 + i), predicate, plane);
						consumer.pair(ValueIds.createId(ValueIds.T_URI, 200 + i), 0);
						consumer.end();
					}
				}
			} finally {
				family.exit(plane, coverage);
			}
		}

		private static long predicate(int ordinal) {
			return ValueIds.createId(ValueIds.T_URI, 10 + ordinal);
		}

		@Override
		public long snapshotRevision() {
			return 7;
		}

		@Override
		public long snapshotId() {
			return 11;
		}

		@Override
		public void ensureSnapshotValid() {
		}

		@Override
		public void close() {
		}
	}

