	private static final class FailingRangeFamily extends PredicateRangeFamily {

		private final AtomicBoolean cancelled = new AtomicBoolean();
		private final AtomicBoolean cancelObservedActiveScanner = new AtomicBoolean();
		private final AtomicInteger activeScanners = new AtomicInteger();
		private final CountDownLatch siblingStarted = new CountDownLatch(1);

		private FailingRangeFamily() {
			super(4);
		}

		@Override
		PredicateRangeScanner newScanner() {
			return new PredicateRangeScanner() {
				@Override
				public void scanOutgoing(boolean explicit, LmdbAdjacencyCoverage coverage, GroupConsumer consumer) {
					scan(explicit, coverage);
				}

				@Override
				public void scanIncoming(boolean explicit, LmdbAdjacencyCoverage coverage, GroupConsumer consumer) {
					scan(explicit, coverage);
				}

				private void scan(boolean explicit, LmdbAdjacencyCoverage coverage) {
					if (!explicit || coverage.selectedPredicateCount() == 0) {
						return;
					}
					int ordinal = ManyRangeFamily.selectedOrdinal(coverage);
					if (ordinal == 0) {
						await(siblingStarted, "the paged sibling range did not start");
						throw new IllegalStateException("injected paged range failure");
					}
					if (ordinal == 1) {
						activeScanners.incrementAndGet();
						siblingStarted.countDown();
						try {
							while (!Thread.currentThread().isInterrupted()) {
								Thread.onSpinWait();
							}
							throw new CancellationException("sibling range interrupted");
						} finally {
							activeScanners.decrementAndGet();
						}
					}
				}
			};
		}

		@Override
		public void cancel() {
			cancelObservedActiveScanner.set(activeScanners.get() != 0);
			cancelled.set(true);
		}
	}

